package com.youth.banner;

import android.content.Context;
import android.util.Log;
import android.view.View;
import android.widget.ImageView;

import com.youth.banner.loader.ImageLoaderInterface;

import java.util.List;

/**
 * Created by Wanghy360 on 2018/11/30.
 */
public class BannerAdapter extends LoopAdapter {
    private int scaleType;
    private List<?> imagesUrls;
    private List<String> titles;
    private ImageLoaderInterface imageLoader;

    public BannerAdapter(int scaleType) {
        this(scaleType, null, null);
    }

    public BannerAdapter(int scaleType, List<?> imagesUrls, List<String> titles) {
        this.scaleType = scaleType;
        this.imagesUrls = imagesUrls;
        this.titles = titles;
    }

    public void setScaleType(int scaleType) {
        this.scaleType = scaleType;
    }

    public void setImagesUrls(List<?> imagesUrls) {
        this.imagesUrls = imagesUrls;
    }

    public void setTitles(List<String> titles) {
        this.titles = titles;
    }

    public void setImageLoader(ImageLoaderInterface imageLoader) {
        this.imageLoader = imageLoader;
    }

    @Override
    public int getCount() {
        return imagesUrls == null ? 0 : imagesUrls.size();
    }

    @Override
    public View getItemView(Context context, int realPosition) {
        ImageView imageView = null;
        if (imageLoader != null) {
            imageView = imageLoader.createImageView(context);
        }
        if (imageView == null) {
            imageView = new ImageView(context);
        }
        setScaleType(imageView);
        if (imageLoader != null)
            imageLoader.displayImage(context, imagesUrls.get(realPosition), imageView);
        else
            Log.e("BannerAdapter", "Please set images loader.");
        return imageView;
    }

    @Override
    public List<String> getTitles() {
        return titles;
    }

    private void setScaleType(View imageView) {
        if (imageView instanceof ImageView) {
            ImageView view = ((ImageView) imageView);
            switch (scaleType) {
                case 0:
                    view.setScaleType(ImageView.ScaleType.CENTER);
                    break;
                case 1:
                    view.setScaleType(ImageView.ScaleType.CENTER_CROP);
                    break;
                case 2:
                    view.setScaleType(ImageView.ScaleType.CENTER_INSIDE);
                    break;
                case 3:
                    view.setScaleType(ImageView.ScaleType.FIT_CENTER);
                    break;
                case 4:
                    view.setScaleType(ImageView.ScaleType.FIT_END);
                    break;
                case 5:
                    view.setScaleType(ImageView.ScaleType.FIT_START);
                    break;
                case 6:
                    view.setScaleType(ImageView.ScaleType.FIT_XY);
                    break;
                case 7:
                    view.setScaleType(ImageView.ScaleType.MATRIX);
                    break;
            }
        }
    }
}

ens;
    private LayoutInflater mInflater;

    private ListAdapterListener mListener;

    public ItemAdapter(Context context, ArrayList <Item> produtos, ListAdapterListener mListener) {
        this.context = context;
        this.itens = produtos;
        if (context != null) {
            mInflater = LayoutInflater.from(context);
        }
        this.mListener = mListener;
    }

    public interface ListAdapterListener {
        void onClickAtItem(Item item);
    }

    @Override
    public int getCount() {
        return itens.size();
    }

    @Override
    public Item getItem(int position) {
        return itens.get(position);
    }

    @Override
    public long getItemId(int position) {
        return position;
    }

    @Override
    public View getView(int position, View view, ViewGroup parent) {

        final Item item = itens.get(position);
        view = mInflater.inflate(R.layout.item_list, null);

        TextView tvTitle = (TextView) view.findViewById(R.id.tv_title);
        tvTitle.setText(item.getTitle());

        TextView tvPrice = (TextView) view.findViewById(R.id.tv_price);
        tvPrice.setText("R$" + String.format("%.2f", item.getPrice()));

        TextView tvSeller = (TextView) view.findViewById(R.id.tv_seller);
        tvSeller.setText(item.getSeller());

        ImageView imageItem = (ImageView) view.findViewById(R.id.image_item);
        if (item.getImageBitmap() != null){
            imageItem.setImageBitmap(item.getImageBitmap());
        } else{
            new DownloadImagesTask(imageItem, item).execute(item.getImageURL());
        }

        Button btnAddCart = (Button) view.findViewById(R.id.btn_add_cart);
        if (mListener != null) {
            btnAddCart.setVisibility(View.VISIBLE);
            btnAddCart.setOnClickListener(new View.OnClickListener() {
                @Override
                public void onClick(View v) {
                    mListener.onClickAtItem(item);
                }
            });
        } else {
            btnAddCart.setVisibility(View.GONE);
        }

        return view;

    }

    public class DownloadImagesTask extends AsyncTask<String, Void, Bitmap> {

        ImageView imageView = null;
        Item item;

        public DownloadImagesTask(ImageView image, Item item) {
            this.item = item;
            imageView = image;
        }

        @Override
        protected Bitmap doInBackground(String... params) {
            return download_Image(params[0]);
        }

        @Override
        protected void onPostExecute(Bitmap result) {
            if (imageView != null) {
                imageView.setImageBitmap(result);
                item.setImageBitmap(result);
            }
        }

        private Bitmap download_Image(String url) {
            Bitmap bm = null;
            try {
                URL aURL = new URL(url);
                URLConnection conn = aURL.openConnection();
                conn.connect();
                InputStream is = conn.getInputStream();
                BufferedInputStream bis = new BufferedInputStream(is);
                bm = BitmapFactory.decodeStream(bis);
                bis.close();
                is.close();
            } catch (IOException e) {
                Log.e("Hub", "Error getting the image from server : " + e.getMessage().toString());
            }
            return bm;
        }
    }
}

