        let selectedIndex = n.userInfo?[WBStatusCellBrowserPhotoSelectedIndexKey] as? Int,
        let imageViewList = n.userInfo?[WBStatusCellBrowserPhotoImageViewKey] as? [UIImageView]
        else {
            return
