	while (l!=fname.end() && l.get().ascii_value()!='.')
	{
		*(s++)=l.get().ascii_value();
		++l;
	}

	*s=0;

	if (sscanf(st,"%x",&x))
	{
		return x;
	}
	else
	{
		return 0;
	}
}

