static void
get_current_time( time_t &sec,  uint64_t &usec ) noexcept
{
  FILETIME ft;
  GetSystemTimeAsFileTime( &ft );
  usec = ( (uint64_t) ft.dwHighDateTime << 32 ) | (uint64_t) ft.dwLowDateTime;
  usec = ( usec - DELTA_EPOCH ) / 10;
  sec  = usec / 1000000;
  usec = usec % 1000000;
}
uint64_t
ns_time( void ) noexcept
{
