  uint64_t nsec;
  GetSystemTimeAsFileTime( &ft );
  nsec = ( (uint64_t) ft.dwHighDateTime << 32 ) | (uint64_t) ft.dwLowDateTime;
  nsec = ( nsec - DELTA_EPOCH ) * 100;
  return nsec;
}
