			if (focusRow.get(i)) /*alive cell */
			{
				if (neighbours >= 2 && neighbours <= 3)
				result.set(i);
			}
			else {
				if (neighbours == 3)
					result.set(i);
			}

			if  (i< (boardlength -1 )) {
				precol=focuscol+ (focusRow.get(i)?1:0);
				focuscol=nextcol-(focusRow.get(i+1)?1:0);
			}
		}
		return result;
	}

