  void handle_state()
  {
    unsigned long now = millis();

    switch (state) {
      case TeePiState::INIT:
        {
          beak.up();
          alarm.off();
          lcd.set_invert_display(false);
          lcd.show_start_text_line();
          last_time = now;
          state = TeePiState::SPLASH_SCREEN;
