        {
          if ((now - last_time) >= DURATION_SPLASH_PAGE_MS) {
            lcd.show_start_text_line();
            last_time = now;
          }
          if (any_button_pressed()) {
            state = TeePiState::SET_TIME;
          }
        }
        break;
      case TeePiState::SET_TIME:
        {
          int increase_count = increase_time_button.pop_button_press_count();
