void DDSurf_Init( void )
{
    int i;
    DDSurfMemUsed =0;
    for( i = 0 ; i < MAXDDSURFBLOCKS ; i++ )
    {
        DDSurfBlockUsed[i] = FALSE;
        DDSurfBlockPnts[i] = NULL;
        DDSurfBlockSize[i] = 0;
    }
