/*-------------------------------------------------------------------
    Procedure   :   X Exec Find Free...
    Input       :   void
    Output      :   int Free memblock -1 if none
-------------------------------------------------------------------*/
int DDSurf_FindFree( void )
{
    int i;
    for( i = 0 ; i < MAXDDSURFBLOCKS ; i++ )
    {
        if( !DDSurfBlockUsed[i] )
        {
            DDSurfBlocksUsed++;
            return i;
        }
    }
    return -1;
}
/*-------------------------------------------------------------------
