{
    int i;
    for( i = 0 ; i < MAXDDSURFBLOCKS ; i++ )
    {
        if( DDSurfBlockUsed[i] && ( DDSurfBlockPnts[i] == Pnt ) )
            return i;
    }
    return -1;
}

