class LazySingleton {
    //volatile保证底层不会指令重排序
    private volatile static LazySingleton instance;
    private LazySingleton() { }

    public static LazySingleton getInstance() {

        if (instance == null) {

            synchronized (LazySingleton.class) {
                if (instance == null) {
                    instance = new LazySingleton();
                    //字节码层面
                    /*
                    *JIT，CPU
                    * 1.分配空间
                    * 2.初始化
                    * 3.引用赋值
                    * */
                }
            }
        }
        return instance;
    }
}

