  }

  @Override
  protected void stop() throws Exception {
    if (isRunning()) {
      synchronized (this) {
        ConcurrencyUtil.shutdownGracefully(processor, 2, TimeUnit.SECONDS);
      }
    }
    disconnect();
  }

  @Override
  public synchronized boolean isStarted() {
    return started.get() && isRunning();
  }

