void imapcollectcleanunittag(imap *map, const ireflist *list) {
	irefjoint *joint = ireflistfirst(list);
	while (joint) {
		iunit *u = icast(iunit, joint->value);
		_state_remove(u->state, EnumUnitStateSearching);
		joint = joint->next;
	}
}

